using Microsoft.FeatureManagement;

/// <summary>
/// ميزة غير مكتملة؟ ادمجها مُطفأة.
/// النتيجة: دمج يومي، لا فروع طويلة، ونشر بلا إطلاق ميزة.
/// </summary>
public sealed class OrderExportFeature(IFeatureManager features)
{
    public const string Flag = "order-export";

    public async Task<IResult> ExportAsync(HttpContext http, IOrdersApi api, CancellationToken ct)
    {
        if (!await features.IsEnabledAsync(Flag))
            return Results.NotFound();          // ميزة مُطفأة = غير موجودة عمليًا

        // إتاحة تدريجية لمن له دور معيّن — بدل الإطلاق للجميع
        return Results.Ok(await api.GetExportAsync(ct));
    }
}

/*
 إعدادات appsettings.json:
   "FeatureManagement": {
     "order-export": false
   }
 ولوحة تحكم/متغير بيئة لتشغيلها لكل بيئة (FeatureGate في ASP.NET Core).
*/
